  if (!['needs_owner', 'approved'].includes(p.status)) return refuse('post_locked', `bài #${p.Id} đang ${p.status}: chỉ sửa được bài đang chờ duyệt hoặc đã duyệt mà chưa đăng`);
  if (!String(input.note || '').trim()) return refuse('nothing_to_revise', 'cần góp ý của sếp về chữ (note); đổi hình thì set_picture, hong viết lại');
  return [{ json: { ok: true, revise: true, post_id: p.Id } }];
}
if (!idea || !String(idea.theme || '').trim()) return refuse('idea_missing', `ý tưởng #${input.idea_id} hong có trong kho, hoặc chưa có theme`);
const open = posts.filter((p) => p.idea_id === idea.Id && ['writing', 'needs_owner'].includes(p.status));
const again = input.again === true || input.again === 'true';
if (open.length && !again) return refuse('already_writing', `ý tưởng #${idea.Id} đang có bài #${open[0].Id} (${open[0].status}); muốn viết thêm bài nữa thì gọi lại với again = true`);
