const type = TYPES.includes(input.content_type) ? input.content_type : (String(idea.owner_words || '').trim() ? 'story' : 'observation');
// Offer cadence: two per month, counting offers written, queued or published this month.
const month = DateTime.now().setZone(TZ).toFormat('yyyy-MM');
const offers = posts.filter((p) => p.content_type === 'offer' && !['rejected', 'failed'].includes(p.status)
  && parseDt(p.scheduled_for || p.created_at).toFormat('yyyy-MM') === month);
if (type === 'offer' && offers.length >= 2) return refuse('offer_cadence', `tháng này đã có ${offers.length} bài offer (#${offers.map((p) => p.Id).join(', #')}), tối đa 2`);
return [{ json: { ok: true, idea_id: idea.Id, content_type: type } }];

