const s = settingsOf('Settings');
const reply_to = $('When called').first().json.reply_to || '';
const TYPE = { observation: 'Observation', story: 'Story', education: 'Education', offer: 'Offer' };
const button = (label, type, a) => ({
  tag: 'column', width: 'auto',
  elements: [{ tag: 'button', type, text: { tag: 'plain_text', content: label }, behaviors: [{ type: 'callback', value: { a, id: p.post_id, t: p.approval_token } }] }],
});
const why = $('Write task').first().json.task.why_today;
const notes = [];
if (p.check.pass) notes.push(`✅ Qua 3 câu hỏi${p.rewrites ? ' sau 1 lần viết lại' : ''}.`);
else notes.push(`⚠️ Viết lại 1 lần vẫn rớt: ${p.check.issues.map((i) => `**${i.point}** — ${i.why}`).join('; ')}`);
if (p.check.note) notes.push(`⚠️ ${p.check.note}`);
for (const i of p.issues.filter((x) => x.code === 'image_failed')) notes.push(`⚠️ ${i.detail}`);
if (!p.image_key) notes.push(`📷 Chưa có hình, bài lên dạng chữ. Gợi ý: ${p.picture_hint}. Muốn có hình thì reply ảnh vào thẻ này.`);
notes.push(`Dẫn tới: ${p.leads_to_offer}${why ? ` · Sao hôm nay: ${why}` : ''}`);
const elements = [{ tag: 'div', text: { tag: 'plain_text', content: p.text } }];
if (p.image_key) elements.push({ tag: 'img', img_key: p.image_key, alt: { tag: 'plain_text', content: p.picture_hint.slice(0, 100) } });
elements.push({ tag: 'hr' }, { tag: 'markdown', content: notes.join('\n') },
  { tag: 'column_set', flex_mode: 'flow', columns: [button('Duyệt', 'primary', 'approve'), button('Bỏ', 'danger', 'reject')] },
  { tag: 'markdown', content: 'Muốn sửa chỗ nào thì reply vào thẻ này.' });
const card = {
  schema: '2.0',
  header: { title: { tag: 'plain_text', content: `Bài #${p.post_id} · ${TYPE[p.content_type] || p.content_type}${$('When called').first().json.revise ? ' · đã sửa theo ý sếp' : ''}` }, template: p.status === 'ok' ? 'blue' : 'orange' },
  body: { elements },
};
const content = JSON.stringify(card);
return [{ json: reply_to
  ? { url: `https://open.larksuite.com/open-apis/im/v1/messages/${reply_to}/reply`, body: { msg_type: 'interactive', content, reply_in_thread: true } }
  : { url: `https://open.larksuite.com/open-apis/im/v1/messages?receive_id_type=${s.lark_chat_id ? 'chat_id' : 'open_id'}`, body: { receive_id: s.lark_chat_id || s.lark_open_id, msg_type: 'interactive', content } } }];

// Lark answers HTTP 200 with a non-zero code on some errors.
if ($json.code !== 0) throw new Error(`Lark refused the card of post #${$('Post row').first().json.post_id}: ${$json.code} ${$json.msg}`);
const p = $('Post row').first().json;
return [{ json: { status: p.status, payload: { post_id: p.post_id, text: p.text, content_type: p.content_type, image: p.image_key || null }, issues: p.issues } }];
